use jobrunner::{run_job, FakeSleeper, RetryConfig, RetryError};

#[test]
fn public_api_retries_transient_failures_and_caps_delay() {
    let config = RetryConfig::new(4, 8, 10);
    let mut sleeper = FakeSleeper::default();
    let mut calls = 0;

    let result = run_job(&config, &mut sleeper, || {
        calls += 1;
        if calls < 4 {
            Err(RetryError::Transient("temporary outage".into()))
        } else {
            Ok(())
        }
    });

    assert_eq!(result, Ok(()));
    assert_eq!(calls, 4);
    assert_eq!(sleeper.sleeps, vec![8, 10, 10]);
}

#[test]
fn public_api_does_not_retry_permanent_failures() {
    let config = RetryConfig::new(5, 1, 100);
    let mut sleeper = FakeSleeper::default();
    let mut calls = 0;

    let result = run_job(&config, &mut sleeper, || {
        calls += 1;
        Err(RetryError::Permanent("invalid job".into()))
    });

    assert_eq!(result, Err(RetryError::Permanent("invalid job".into())));
    assert_eq!(calls, 1);
    assert!(sleeper.sleeps.is_empty());
}

#[test]
fn public_api_counts_initial_call_in_attempt_limit() {
    let config = RetryConfig::new(2, 3, 100);
    let mut sleeper = FakeSleeper::default();
    let mut calls = 0;

    let result = run_job(&config, &mut sleeper, || {
        calls += 1;
        Err(RetryError::Transient("still unavailable".into()))
    });

    assert_eq!(result, Err(RetryError::Transient("still unavailable".into())));
    assert_eq!(calls, 2);
    assert_eq!(sleeper.sleeps, vec![3]);
}

